# orders.py - one module per table, rules over the whole set
def overdue(conn, as_of):
    return conn.execute(
        select(orders.c.id, orders.c.due, orders.c.total).where(orders.c.due < as_of)
    ).all()                                   # list[Row] is the record set

def total_of(rows):
    return sum(row.total for row in rows)

def flag_overdue(conn, as_of):
    conn.execute(update(orders).where(orders.c.due < as_of).values(flagged=True))
